{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/e12-self-review-sonnet-t5t6-20260927T000002Z/cell-eqgyJL/src/policies.js","content":"/**
 * Per-key state machines for the two policy kinds. Both keep independent
 * state per key, advance lazily on first use, and expose the same
 * advance/allows/record protocol so routes can drive them uniformly.
 */

export class TokenBucket {
  constructor(capacity, refill, per) {
    this.capacity = capacity
    this.refill = refill
    this.per = per
    this.byKey = new Map()
  }

  advance(key, tick) {
    const state = this.byKey.get(key)
    if (!state) {
      this.byKey.set(key, { numerator: this.capacity * this.per, lastTick: tick })
      return
    }
    const delta = tick - state.lastTick
    if (delta > 0n) {
      const max = this.capacity * this.per
      state.numerator += this.refill * delta
      if (state.numerator > max) state.numerator = max
      state.lastTick = tick
    }
  }

  allows(key) {
    return this.byKey.get(key).numerator >= this.per
  }

  record(key) {
    this.byKey.get(key).numerator -= this.per
  }
}

export class SlidingWindow {
  constructor(limit, span) {
    this.limit = limit
    this.span = span
    this.byKey = new Map()
  }

  advance(key, tick) {
    let state = this.byKey.get(key)
    if (!state) {
      state = { ticks: [] }
      this.byKey.set(key, state)
    }
    const threshold = tick - this.span
    let drop = 0
    while (drop < state.ticks.length && state.ticks[drop] <= threshold) drop++
    if (drop > 0) state.ticks.splice(0, drop)
  }

  allows(key) {
    return BigInt(this.byKey.get(key).ticks.length) < this.limit
  }

  record(key, tick) {
    this.byKey.get(key).ticks.push(tick)
  }
}
"}

