{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/e12-self-review-sonnet-t5t6-20260927T000002Z/cell-eqgyJL/src/simulate.js","content":"/**
 * Replays parsed events through their routed policies and tallies verdicts.
 */

import { TokenBucket, SlidingWindow } from './policies.js'

function buildInstances(policies) {
  const instances = new Map()
  for (const [name, def] of policies) {
    instances.set(
      name,
      def.type === 'bucket' ? new TokenBucket(def.capacity, def.refill, def.per) : new SlidingWindow(def.limit, def.span),
    )
  }
  return instances
}

function makeRouteFinder(routes) {
  const byLengthDesc = [...routes].sort((a, b) => b.prefix.length - a.prefix.length)
  return (key) => byLengthDesc.find((route) => key.startsWith(route.prefix)) ?? null
}

/**
 * @param {{ policies: Map<string, object>, routes: Array<object>, events: Array<object> }} parsed
 * @returns {{ results: Array<object>, perKey: Map<string, {allowed: bigint, denied: bigint}>, totalAllowed: bigint, totalDenied: bigint }}
 */
export function simulate({ policies, routes, events }) {
  const instances = buildInstances(policies)
  const findRoute = makeRouteFinder(routes)

  const results = []
  const perKey = new Map()
  let totalAllowed = 0n
  let totalDenied = 0n

  for (const event of events) {
    const route = findRoute(event.key)
    let verdict

    if (!route) {
      verdict = { allow: true }
    } else {
      const policyObjs = route.policyNames.map((name) => instances.get(name))
      for (const policy of policyObjs) policy.advance(event.key, event.tick)

      let denyingPolicy = null
      for (let i = 0; i < policyObjs.length; i++) {
        if (!policyObjs[i].allows(event.key)) {
          denyingPolicy = route.policyNames[i]
          break
        }
      }

      if (denyingPolicy) {
        verdict = { allow: false, policy: denyingPolicy }
      } else {
        for (const policy of policyObjs) policy.record(event.key, event.tick)
        verdict = { allow: true }
      }
    }

    results.push({ tick: event.tick, key: event.key, ...verdict })

    if (!perKey.has(event.key)) perKey.set(event.key, { allowed: 0n, denied: 0n })
    const tally = perKey.get(event.key)
    if (verdict.allow) {
      tally.allowed++
      totalAllowed++
    } else {
      tally.denied++
      totalDenied++
    }
  }

  return { results, perKey, totalAllowed, totalDenied }
}
"}

