{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/e12-self-review-sonnet-t5t6-20260927T000002Z/cell-eqgyJL/src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js replay` verdicts every event of the limiter
 * file read from standard input, and `node src/cli.js summary` totals the
 * verdicts per key.
 */

import { readFileSync } from 'node:fs'
import { parseLimiterFile, ParseError } from './parse.js'
import { simulate } from './simulate.js'

function fail(message) {
  process.stderr.write(`error: ${message}\n`)
  process.exit(2)
}

function main() {
  const argv = process.argv.slice(2)
  if (argv.length !== 1 || (argv[0] !== 'replay' && argv[0] !== 'summary')) {
    fail('usage: cli.js replay|summary')
  }
  const mode = argv[0]

  const input = readFileSync(0, 'utf8')

  let parsed
  try {
    parsed = parseLimiterFile(input)
  } catch (error) {
    if (error instanceof ParseError) fail(`line ${error.line}: ${error.reason}`)
    throw error
  }

  const { results, perKey, totalAllowed, totalDenied } = simulate(parsed)

  let out = ''
  if (mode === 'replay') {
    for (const r of results) {
      out += r.allow ? `${r.tick} ${r.key} allow\n` : `${r.tick} ${r.key} deny ${r.policy}\n`
    }
  } else {
    for (const key of [...perKey.keys()].sort()) {
      const tally = perKey.get(key)
      out += `${key} allowed=${tally.allowed} denied=${tally.denied}\n`
    }
    out += `total allowed=${totalAllowed} denied=${totalDenied}\n`
  }

  process.stdout.write(out)
  process.exit(0)
}

main()
"}

