 * Parses a limiter file into declared policies, routes and events.
 */

const TOKEN_RE = /^[A-Za-z0-9_./:-]+$/
const UNSIGNED_INT_RE = /^(0|[1-9][0-9]*)$/

export class ParseError extends Error {
  constructor(line, reason) {
    super(`line ${line}: ${reason}`)
    this.line = line
    this.reason = reason
  }
}

function requireToken(token, line, invalidMessage) {
  if (!TOKEN_RE.test(token)) throw new ParseError(line, invalidMessage)
}

function parseCount(token, field, min, line) {
  if (!UNSIGNED_INT_RE.test(token)) {
    throw new ParseError(line, `${field} must be an integer of at least ${min}`)
  }
  const value = BigInt(token)
  if (value < min) {
    throw new ParseError(line, `${field} must be an integer of at least ${min}`)
  }
  return value
}

/**
 * @param {string} text the raw limiter file contents
 * @returns {{ policies: Map<string, object>, routes: Array<object>, events: Array<object> }}
 */
export function parseLimiterFile(text) {
  const rawLines = text.split('\n')
  if (rawLines.length > 0 && rawLines[rawLines.length - 1] === '') rawLines.pop()

  const policies = new Map()
  const routes = []
  const routePrefixes = new Set()
  const events = []
  let seenEvent = false
  let lastTick = null

  for (let i = 0; i < rawLines.length; i++) {
    const line = i + 1
    const trimmed = rawLines[i].trim()
    if (trimmed === '' || trimmed.startsWith('#')) continue

    const tokens = trimmed.split(/\s+/)
    const directive = tokens[0]

    if (directive !== 'bucket' && directive !== 'window' && directive !== 'route' && directive !== 'event') {
      throw new ParseError(line, `unknown directive ${directive}`)
    }
    if (directive !== 'event' && seenEvent) {
      throw new ParseError(line, 'declarations must come before the first event')
    }

    if (directive === 'bucket') {
      if (tokens.length !== 5) throw new ParseError(line, 'expected bucket <name> <capacity> <refill> <per>')
      const [, name, capT, refT, perT] = tokens
      requireToken(name, line, `invalid policy name ${name}`)
      const capacity = parseCount(capT, 'capacity', 1n, line)
      const refill = parseCount(refT, 'refill', 0n, line)
      const per = parseCount(perT, 'per', 1n, line)
      if (policies.has(name)) throw new ParseError(line, `policy ${name} is declared twice`)
      policies.set(name, { type: 'bucket', capacity, refill, per })
    } else if (directive === 'window') {
      if (tokens.length !== 4) throw new ParseError(line, 'expected window <name> <limit> <span>')
      const [, name, limT, spanT] = tokens
      requireToken(name, line, `invalid policy name ${name}`)
      const limit = parseCount(limT, 'limit', 0n, line)
      const span = parseCount(spanT, 'span', 1n, line)
      if (policies.has(name)) throw new ParseError(line, `policy ${name} is declared twice`)
      policies.set(name, { type: 'window', limit, span })
    } else if (directive === 'route') {
      if (tokens.length < 3) throw new ParseError(line, 'expected route <prefix> <policy>...')
      const prefix = tokens[1]
      requireToken(prefix, line, `invalid route prefix ${prefix}`)
      const policyNames = tokens.slice(2)
      for (const name of policyNames) {
        requireToken(name, line, `invalid policy name ${name}`)
        if (!policies.has(name)) throw new ParseError(line, `unknown policy ${name}`)
      }
      if (routePrefixes.has(prefix)) throw new ParseError(line, `prefix ${prefix} is routed twice`)
      routePrefixes.add(prefix)
      routes.push({ prefix, policyNames })
    } else {
      if (tokens.length !== 3) throw new ParseError(line, 'expected event <tick> <key>')
      const [, tickT, key] = tokens
      const tick = parseCount(tickT, 'tick', 0n, line)
      requireToken(key, line, `invalid key ${key}`)
      if (lastTick !== null && tick < lastTick) {
        throw new ParseError(line, `tick ${tick} is before tick ${lastTick}`)
      }
      lastTick = tick
      seenEvent = true
      events.push({ tick, key, line })
    }
  }

  return { policies, routes, events }
}
